const D = { density:.6, energy:.62, speed:1, turb:.55, scale:1, trail:.55, hue:210, x:.5, y:.5, style:'spectral', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = 6.28318530718;
const clp = (v,a,b)=> v<a?a:v>b?b:v;
const st = P.style;
const light = (st==='ink');                                   // dark-on-pale subtractive vs additive glow

// coarse half-canvas feedback buffer (aspect-matched, capped), cached on size
const BW = Math.min(520, Math.max(180, Math.round(width*0.5)));
const BH = Math.max(100, Math.round(BW*height/width));
const key = BW+'x'+BH;
const N = Math.floor(1000 + P.density*2600);                  // ~1300..3600 particles

if (S.key!==key || S.seedUsed!==P.seed || !S.buf){
  S.key=key; S.seedUsed=P.seed;
  if (S.buf && S.buf.remove) S.buf.remove();
  S.buf = createGraphics(BW,BH); S.buf.pixelDensity(1); S.buf.colorMode(HSB,360,100,100,100);
  S.needFill = true; S.ps = null;
  let z = ((P.seed|0)*2654435761 + 12345) >>> 0;
  S.rnd = ()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.noff = S.rnd()*1000;
}
const rnd = S.rnd;
if (!S.ps || S.ps.length!==N){
  const arr=[];
  for (let i=0;i<N;i++) arr.push({ x:rnd()*BW, y:rnd()*BH, px:0, py:0, life:(rnd()*120)|0 });
  S.ps=arr;
}
const g = S.buf;

// per-style ground tone (guarantees luminance floor; pale for ink)
let bh,bs,bb;
if (light){ bh=230; bs=12; bb=94; }
else if (st==='ember'){ bh=16; bs=82; bb=9; }
else if (st==='aurora'){ bh=205; bs=58; bb=8; }
else if (st==='neon'){ bh=272; bs=62; bb=6; }
else { bh=236; bs=56; bb=9; }                                 // spectral deep indigo

if (S.needFill){ g.push(); g.blendMode(BLEND); g.noStroke(); g.fill(bh,bs,bb,100); g.rect(0,0,BW,BH); g.pop(); S.needFill=false; }

// slow trail fade toward the ground tone
const fadeA = light ? (7 + (1-P.trail)*20) : (3.5 + (1-P.trail)*13);
g.push(); g.blendMode(BLEND); g.noStroke(); g.fill(bh,bs,bb, fadeA); g.rect(0,0,BW,BH); g.pop();

// field + motion (all rhythm from K; audio ON TOP)
const intn = K.intensity!=null?K.intensity:.6;
const zt   = K.t*(0.05 + P.speed*0.06) + S.noff;              // real-time drift, never re-phases
const sc   = 0.010 / clp(P.scale,0.3,3);
const oX   = (P.x-0.5)*3, oY = (P.y-0.5)*3;                   // anchor biases the flow pattern
const eps  = 1.4;
const turb = 0.7 + P.turb*2.3 + A.lowmid*1.4;
const step = (0.9 + P.speed*1.6) * (0.8 + intn*0.5) * (1 + A.bass*0.7);
const bri  = 0.7 + P.energy*0.7 + intn*0.3 + A.rms*0.6 + K.pulse*0.28*P.energy;
const hueDrift = K.t*3 + P.hue + K.section*8;
const nsv = (x,y)=> noise(x*sc+oX, y*sc+oY, zt);

g.push();
g.blendMode(light ? BLEND : ADD);
g.strokeWeight((light?1.15:1.0) * (0.8 + P.energy*1.2));
for (let i=0;i<N;i++){
  const p=S.ps[i];
  const vx = nsv(p.x, p.y+eps) - nsv(p.x, p.y-eps);
  const vy = -(nsv(p.x+eps, p.y) - nsv(p.x-eps, p.y));
  const mag = Math.sqrt(vx*vx+vy*vy);
  const ang = Math.atan2(vy, vx) * turb;
  const nx = p.x + Math.cos(ang)*step;
  const ny = p.y + Math.sin(ang)*step;
  p.life++;
  if (nx<0||nx>=BW||ny<0||ny>=BH || p.life>150){ p.x=rnd()*BW; p.y=rnd()*BH; p.life=0; continue; }
  p.px=p.x; p.py=p.y; p.x=nx; p.y=ny;
  let h,s,b,al;
  if (light){ h=232+Math.cos(ang)*22; s=clp(46+mag*260,20,80); b=20+Math.sin(ang*2)*8; al=20+P.energy*24; }
  else if (st==='ember'){ const sp=clp(mag*260,0,1); h=6+sp*48; s=96-sp*58; b=(44+sp*56)*bri; al=30+P.energy*30; }
  else if (st==='aurora'){ h=(150+Math.cos(ang)*95+hueDrift*0.4)%360; s=82; b=(52+mag*220)*bri; al=26+P.energy*28; }
  else if (st==='neon'){ h=(hueDrift+degrees(ang))%360; s=95; b=100*Math.min(1,bri); al=30+P.energy*32; }
  else { h=(hueDrift+degrees(ang)*0.9+720)%360; s=72; b=(58+mag*210)*bri; al=28+P.energy*30; }   // spectral
  g.stroke(((h%360)+360)%360, clp(s,0,100), clp(b,0,100), clp(al,0,100));
  g.line(p.px,p.py,p.x,p.y);
}
g.pop();
g.blendMode(BLEND);

// composite to main (opaque bg by default; tint for VJ alpha)
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g, 0,0, width,height);
pop();
